import os
import json
import uuid
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class DeadLetterPublisher:
    def __init__(
        self,
        source_queue_url: str,
        dead_letter_queue_url: str,
        region_name: Optional[str] = None,
    ) -> None:
        self.source_queue_url = source_queue_url
        self.dead_letter_queue_url = dead_letter_queue_url
        self.sqs = boto3.client("sqs", region_name=region_name)

    def _send_to_dead_letter(self, message_body: str, attributes: Optional[Dict[str, Any]] = None) -> None:
        message_attributes = {
            "OriginalQueue": {
                "DataType": "String",
                "StringValue": self.source_queue_url,
            },
            "FailureId": {
                "DataType": "String",
                "StringValue": str(uuid.uuid4()),
            },
        }

        if attributes:
            for key, value in attributes.items():
                message_attributes[key] = {
                    "DataType": "String",
                    "StringValue": json.dumps(value) if not isinstance(value, str) else value,
                }

        self.sqs.send_message(
            QueueUrl=self.dead_letter_queue_url,
            MessageBody=message_body,
            MessageAttributes=message_attributes,
        )

    def process_messages(self) -> None:
        while True:
            response = self.sqs.receive_message(
                QueueUrl=self.source_queue_url,
                MaxNumberOfMessages=10,
                WaitTimeSeconds=20,
                MessageAttributeNames=["All"],
                AttributeNames=["All"],
            )

            messages = response.get("Messages", [])
            if not messages:
                break

            for msg in messages:
                receipt_handle = msg["ReceiptHandle"]
                body = msg.get("Body", "")
                attrs = msg.get("MessageAttributes", {})

                try:
                    self._handle_message(body, attrs)
                    self.sqs.delete_message(
                        QueueUrl=self.source_queue_url,
                        ReceiptHandle=receipt_handle,
                    )
                except Exception as exc:
                    failure_attrs = {
                        "ErrorType": type(exc).__name__,
                        "ErrorMessage": str(exc),
                    }
                    self._send_to_dead_letter(body, {**attrs, **failure_attrs})
                    self.sqs.delete_message(
                        QueueUrl=self.source_queue_url,
                        ReceiptHandle=receipt_handle,
                    )

    def _handle_message(self, body: str, attributes: Dict[str, Any]) -> None:
        if not body:
            raise ValueError("Empty message body")

        payload = json.loads(body)
        if payload.get("should_fail", False):
            raise RuntimeError("Message processing failed intentionally")

        _ = attributes


def main() -> None:
    source_queue_url = os.environ["SOURCE_QUEUE_URL"]
    dead_letter_queue_url = os.environ["DEAD_LETTER_QUEUE_URL"]
    region_name = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")

    publisher = DeadLetterPublisher(
        source_queue_url=source_queue_url,
        dead_letter_queue_url=dead_letter_queue_url,
        region_name=region_name,
    )
    publisher.process_messages()


if __name__ == "__main__":
    main()
